const g = k => (dv[k] == null ? "" : String(dv[k])).trim();
const problems = [];
const suggestions = {};
let ok = true;
if (!g("first_name") && !g("company_name")) { problems.push({field: "first_name", issue: "missing - need at least one name for the booking"}); ok = false; }
if (!g("company_name")) { problems.push({field: "company_name", issue: "missing"}); ok = false; }
const cb = g("callback_number");
if (!/^\+[1-9]\d{6,14}$/.test(cb)) {
  const digits = cb.replace(/\D/g, "");
  if (digits.length === 10) { suggestions["callback_number"] = "+1" + digits; problems.push({field: "callback_number", issue: "not E.164 - apply the suggestion verbatim"}); }
  else { problems.push({field: "callback_number", issue: cb ? "not E.164" : "missing"}); }
  ok = false;
}
if (["America/New_York","America/Chicago","America/Denver","America/Los_Angeles"].indexOf(g("prospect_timezone")) < 0) { problems.push({field: "prospect_timezone", issue: "not IANA"}); ok = false; }
const st = g("selected_time") || g("requested_slot");
if (!st) { problems.push({field: "selected_time", issue: "no confirmed slot"}); ok = false; }
return { data_complete: ok && problems.length === 0, problems, suggestions };
